    if (DUST_CARD[d] && card(e, DUST_CARD[d])) return DUST_CARD_EVERY;
    return d === "ice" && all(e, HIDDEN.sentry16) ? 1.6 : SENTRY_EVERY;
  }
  // her hidden effects read here (data/potentials.json, tools/add_hidden.py): the cards each needs
  // (0.4.1, the testers 2026-11-08) glyph6: Twisting Step + Lunge Glyph, the glyphs her moves leave last 6 s (rwi_glyph_mid)
  var HIDDEN = { uses4: [21310, 21323], sentry16: [21307, 21308, 21322], dust11: [21328, 21329, 21330], pillar: [21308, 21322],
