  function uses(e) { return all(e, HIDDEN.uses4) ? 4 : USES }
  // (0.4.7, the testers 2026-11-13: "There needs to be a limit on glyphs"; the call: at most MAX_OUT of hers out at once,
  // the ones her cards place counted too) a colour's own limit sits inside it: two, three with Third Glyph or Potential
  // Unleashed. capOut() ends the oldest past MAX_OUT with its own end action
  var MAX_OUT = 3;
  function limit(e) { return Math.min(MAX_OUT, LIMIT + (card(e, THIRD) ? 1 : 0) + (card(e, PU) ? 1 : 0)) }
  // her shard bullet: faster with Keen Ice, breaking Strong armor with Universal Enhancement 1
  function shardAct(e) { return (card(e, KEEN) ? "rwi_shard_fast" : "rwi_shard") + (card(e, UNI1) ? "_ab" : "") }
  // her glyph bullet: 12 s, or 20 s with Universal Enhancement 2
  function glyphAct(e) { return card(e, UNI2) ? "rwi_glyph_long" : "rwi_glyph" }
  function glyphLife(e) { return card(e, UNI2) ? 20 : 12 }
  // a white glyph's life (the lead, 2026-11-02: "Give her white glyphs a specific alive time"): Lambda-11's portal, whose
  // firing pace it copies (rmbullet1 EX: TotalDuration 10.0 s), and with Universal Enhancement 2 the black glyph's
  // 12 -> 20 s stretch, 10 x 20 / 12 = 17 s (WHITE_LIFE in steps/weiss_steps.py)
  function whiteLife(e) { return card(e, UNI2) ? 17 : 10 }
  function log(k, m) {
    if (k && S.said[k]) return; if (k) S.said[k] = 1;
    try { if (globalThis.BBTR && BBTR.x && BBTR.x.log) { BBTR.x.log("WEISS " + m); return } } catch (x) {}
    try { CS.System.IO.File.AppendAllText("@ROOT@/modlog.txt", (new Date()).toISOString() + " WEISS " + m + "\n") } catch (x) {}
  }
  function now() { try { return U.FpToFloat(CS.GamePlay.BattleBase.Cur.BattleTimeFp) } catch (x) { return -1 } }
  function fp2(x, y) { return U.Vector2ToFp2(new CS.UnityEngine.Vector2(x, y)) }
  function P(a, k) { var v = ""; try { v = a.GetS(k) } catch (x) { try { v = a.Get(k) } catch (y) {} } return v == null ? "" : String(v) }
  function skill(e) {
