      var o = CS.GamePlay.BattleBase.Cur.BulletMgr.CreateBulletByParams(e, GLYPH_BULLET, fp2(x, y), fp2(dx, dy || 0), U.FloatToFp(1), act, skill(e), null);
      if (!o) log("nob" + act, "bullet " + act + " not created");
