    } catch (x) { log("bx" + act, "bullet " + act + " EXC " + x); return null }
  }
  // Summoning, her talent (D2, KIT_DESIGN version B): the third black-glyph use within CHAIN s of the one before cuts with
  // the Arma Gigas's sword (rwi_talent_sword_<talent level>) through the glyph used. The talent's trigger only marks it
  var TALENT = 201301, CHAIN = 1.6;
  S.chain = S.chain || {};
  function talentLevel(e) {
    try {
      var n = e.TriggerMgr.FindTriggerByIdxRange(TALENT, TALENT);
      return n ? Math.max(1, Math.min(4, Math.round(U.FpToFloat(n.Lvl)))) : 0;
    } catch (x) { return 0 }
