    if (t - c.t > CHAIN) c.n = 0;
    c.n++; c.t = t;
    if (c.n < 3) return;
    c.n = 0;
    bullet(e, "rwi_talent_sword_" + q, x, y, e.Dir, 0);
    if (S.dbg) log(null, "summoning: the sword at level " + q);
  }
  // test hook (wsuite w_sword_show): the sword at level q, 2.5 u ahead of e
  S.sword = function (e, q) { return !!bullet(e, "rwi_talent_sword_" + q, +e.Position.x + e.Dir * 2.5, +e.Position.y + 0.9, e.Dir, 0) };
  // her glyphs on the field, oldest first
  function glyphs(e) {
    var out = [];
    try {
      var L = CS.GamePlay.BattleBase.Cur.BulletMgr.BulletList;
      for (var i = 0; i < L.Count; i++) {
        var o = L.get_Item(i);
        try {
          var rc = o.RootCaster || o.Caster; if (!rc || rc.UniqueId !== e.UniqueId) continue;
          var n = String(o.ActionMgr.CurrentActionName);
