    return out;
  }
  // her white glyphs (the tapped Skill's), oldest first
  function whites(e) {
    var out = [];
    try {
      var L = CS.GamePlay.BattleBase.Cur.BulletMgr.BulletList;
      for (var i = 0; i < L.Count; i++) {
        var o = L.get_Item(i);
        try {
          var rc = o.RootCaster || o.Caster; if (!rc || rc.UniqueId !== e.UniqueId) continue;
          if (WHITES[String(o.ActionMgr.CurrentActionName)]) out.push(o);
        } catch (x) {}
      }
