    S.usesBorn = S.usesBorn || {};
    var id = g.UniqueId, same = S.usesBorn[id] === S.born[id], n = (same ? S.uses[id] || 0 : 0) + 1;
    S.uses[id] = n; S.usesBorn[id] = S.born[id];
    bullet(e, "rwi_glyph_flash", +g.Position.x, +g.Position.y, e.Dir, 0);
    if (n >= uses(e)) { try { g.ActionMgr.ChangeAction("rwi_glyph_end") } catch (x) {} delete S.uses[id] }
